# -*- coding: utf-8 -*-
S = "сверка условий с учебником Макарычева 8 (многоколоночные пункты потеряны/искажены при импорте), 29.09"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G8_TB_17_404", "в условии были только пункты а)–г), а ключ и варианты ссылаются на пункты д)–м); условие восстановлено по учебнику (№ 404, 12 выражений); ключ проверен вычислением: подкоренное отрицательно в в), д), з), и), л); в м) значение равно 0 (корень имеет смысл)",
  q="Какие из выражений не имеют смысла:\n" + "\n".join([
    r"а) $\sqrt{2\sqrt{17}-4}$;", r"б) $\sqrt{9-\sqrt{80}}$;", r"в) $\sqrt{8\sqrt{3}-14}$;", r"г) $\sqrt{15-2\sqrt{56}}$;",
    r"д) $\sqrt{\sqrt{11}-3\sqrt{2}}$;", r"е) $\sqrt{2\sqrt{2}-\sqrt{7}}$;", r"ж) $\sqrt{6\sqrt{3}-7\sqrt{2}}$;", r"з) $\sqrt{\sqrt{186}-5\sqrt{13}}$;",
    r"и) $\sqrt{-\sqrt{186}+5\sqrt{7}}$;", r"к) $\sqrt{\sqrt{56}-4\sqrt{2}}$;", r"л) $\sqrt{\sqrt{42}-6\sqrt{5}}$;", r"м) $\sqrt{\sqrt{72}-6\sqrt{2}}$?"]))
E("G8_TB_14_341", "в условии остался только пункт а), а ключ «б»; условие восстановлено по учебнику (№ 341: а) $x^2=30$; б) $7x^2=10$; в) $0{,}2x^2=3$); у б) $x^2=10/7$, оба корня по модулю меньше 2, у а) и в) положительный корень больше 2",
  q="Решите данные уравнения и укажите те из них, у которых оба корня не превосходят числа $2$:\n" + r"а) $x^{2}=30$;" + "\n" + r"б) $7x^{2}=10$;" + "\n" + r"в) $0{,}2x^{2}=3$")
E("G8_TB_35_851", "пункты б)–г) в условии были искажены (не совпадали с учебником № 851), из-за чего в) и г) оба были неверны при $a=2$; восстановлено по учебнику: а) $a^2>2a-3$; б) $a^2+6>4a$; в) $4a-4<a^2$; г) $8a-70<a^2$; неверно при $a=2$ только в) ($(a-2)^2>0$), ключ «в» прежний",
  q="Выберите из данных неравенств такое, которое не является верным при любом значении $a$:\n" + r"а) $a^{2}>2a-3$;" + "\n" + r"б) $a^{2}+6>4a$;" + "\n" + r"в) $4a-4<a^{2}$;" + "\n" + r"г) $8a-70<a^{2}$.")
